#!/usr/bin/env python3
"""Render extracted ``FileInfo`` structures into project-map markdown."""
from __future__ import annotations


def usage_header(map_path: str) -> str:
    return (
        "<!-- AUTO-GENERATED by ~/.claude/project-map — do not edit. -->\n"
        "<!-- Rebuilt on Python edits and on stale prompts. Manual rebuild:\n"
        "     bash ~/.claude/project-map/bin/refresh.sh -->\n\n"
        "# PROJECT_MAP\n\n"
        f"Location: `{map_path}`\n\n"
        "Codebase map: directory tree, every class / function with its\n"
        "signature, line number and docstring. **For any code question,\n"
        "consult this file first** to find the right `path:line`, then read\n"
        "just that span. Use the LSP for callers/references of a symbol.\n"
        "Fall back to a full search only if a symbol is missing here.\n"
    )


def build_tree(paths) -> str:
    root: dict = {}
    for p in sorted(paths):
        parts = p.split("/")
        node = root
        for part in parts[:-1]:
            node = node.setdefault(part + "/", {})
        node[parts[-1]] = None
    lines: list = []

    def walk(node, prefix):
        items = sorted(node.items(), key=lambda kv: (kv[1] is None, kv[0]))
        for i, (name, child) in enumerate(items):
            last = i == len(items) - 1
            lines.append(prefix + ("└── " if last else "├── ") + name)
            if child is not None:
                walk(child, prefix + ("    " if last else "│   "))

    walk(root, "")
    return "\n".join(lines)


def _file_index(files) -> str:
    rows = []
    for f in files:
        toks = []
        for s in f.symbols:
            if s.kind == "function":
                toks.append(f"{s.name}()")
            elif s.kind == "method":
                continue
            else:                       # class / interface / type / enum
                toks.append(f"{s.name}({s.kind})")
        tail = ", ".join(toks) if toks else "_(no top-level symbols)_"
        note = f"  ⚠ {f.error}" if f.error else ""
        rows.append(f"- `{f.path}` — {tail}{note}")
    return "\n".join(rows)


def _sym_line(s) -> str:
    deco = ""
    if s.decorators:
        deco = " [" + " ".join("@" + d for d in s.decorators) + "]"
    doc = f" — {s.doc}" if s.doc else ""
    if s.kind == "class":
        bases = f"({', '.join(s.bases)})" if s.bases else ""
        return f"- L{s.lineno} `class {s.name}{bases}`{deco}{doc}"
    if s.kind == "method":
        return f"  - L{s.lineno} `{s.name}{s.signature}`{deco}{doc}"
    return f"- L{s.lineno} `{s.kw} {s.name}{s.signature}`{deco}{doc}"


def _detail(files) -> str:
    out = []
    for f in files:
        head = f"### `{f.path}`"
        if f.module_doc:
            head += f" — {f.module_doc}"
        out.append(head)
        if f.error:
            out += [f"- ⚠ {f.error}", ""]
            continue
        if not f.symbols:
            out += ["- _(no classes or functions)_", ""]
            continue
        out += [_sym_line(s) for s in f.symbols]
        out.append("")
    return "\n".join(out)


def render_full(files, tree: str, map_path: str) -> str:
    return "\n".join([
        usage_header(map_path),
        "\n## Directory tree\n\n```\n" + tree + "\n```\n",
        "\n## File index\n\n" + _file_index(files) + "\n",
        "\n## Symbols\n\n" + _detail(files) + "\n",
    ])


def render_summary(files, tree: str, map_path: str) -> str:
    head = (
        "## project-map (compact index)\n"
        f"Full detail (signatures + line numbers): `{map_path}`\n"
        "Code question → find the file here, read the map for the exact\n"
        "`path:line`, then open just that span. Use the LSP for\n"
        "callers/references. Full search only if a symbol is absent.\n"
    )
    return (head + "\n### tree\n```\n" + tree + "\n```\n\n"
            "### symbols by file\n" + _file_index(files) + "\n")
